     9	import com.pousadamarealta.services.HostelNotificationListener;
    10	import com.pousadamarealta.services.ReservationEventPublisher;
    11	import io.javalin.Javalin;
    12	import io.javalin.json.JsonMapper;
    13	import java.lang.reflect.Type;
    14	import org.slf4j.Logger;
    15	import org.slf4j.LoggerFactory;
    16	
    17	public class Main {
    18	  private static final Logger log = LoggerFactory.getLogger(Main.class);
    19	
    20	  public static void main(String[] args) throws Exception {
    21	    String dbUrl = System.getenv("DB_URL");
    22	    String dbUser = System.getenv("DB_USER");
    23	    String dbPassword = System.getenv("DB_PASSWORD");
    24	    String portStr = System.getenv("PORT");
    25	    int port = portStr != null ? Integer.parseInt(portStr) : 7070;
    26	
    27	    if (dbUrl == null || dbUser == null || dbPassword == null) {
    28	      throw new IllegalArgumentException("DB_URL, DB_USER, and DB_PASSWORD must be set");
    29	    }
    30	
    31	    log.info("Initializing database...");
    32	    Database.initialize(dbUrl, dbUser, dbPassword);
    33	    log.info("Database initialized");
    34	
    35	    log.info("Registering event listeners...");
    36	    ReservationEventPublisher.subscribe(new HostelNotificationListener());
    37	
    38	    ObjectMapper objectMapper = new ObjectMapper();
    39	
    40	    Javalin app = Javalin.create(config -> {
    41	      config.jsonMapper(new JsonMapper() {
    42	        @Override
    43	        public <T> T fromJsonString(String json, Type targetType) {
    44	          try {
    45	            return objectMapper.readValue(json, objectMapper.constructType(targetType));
    46	          } catch (Exception e) {
    47	            throw new RuntimeException(e);
    48	          }
    49	        }
    50	
    51	        @Override
    52	        public String toJsonString(Object obj, Type type) {
    53	          try {
    54	            return objectMapper.writeValueAsString(obj);
    55	          } catch (Exception e) {
    56	            throw new RuntimeException(e);
    57	          }
    58	        }
    59	      });
    60	    });
    61	
    62	    app.get("/rooms", RoomController::listRooms);
    63	    app.post("/reservations", ReservationController::createReservation);
    64	    app.get("/reservations/{id}", ReservationController::getReservation);
    65	    app.post("/reservations/{id}/confirmation", ReservationController::confirmReservation);
    66	    app.post("/reservations/{id}/cancellation", ReservationController::cancelReservation);
    67	    app.post("/reservations/{id}/check-in", ReservationController::checkInReservation);
    68	    app.post("/reservations/{id}/check-out", ReservationController::checkOutReservation);
    69	    app.get("/reservations/{id}/document", ReservationController::getDocument);
    70	    app.get("/messages", MessageController::listMessages);
    71	    app.get("/reports/occupancy", ReportController::getOccupancy);
    72	    app.get("/reports/revenue", ReportController::getRevenue);
    73	
    74	    app.exception(Exception.class, (e, ctx) -> {
    75	      if (e.getMessage() == null || e.getMessage().isEmpty()) {
    76	        ctx.status(500);
    77	        ctx.json(new java.util.HashMap<>(java.util.Map.of(
    78	            "error", "INTERNAL_ERROR",
    79	            "message", "Erro interno do servidor"
    80	        )));
    81	      }
    82	    });
