    10	public class ReportController {
    11	  private static final Logger log = LoggerFactory.getLogger(ReportController.class);
    12	  private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    13	
    14	  public static void getOccupancy(Context ctx) {
    15	    try {
    16	      String dateStr = ctx.queryParam("date");
    17	      if (dateStr == null) {
    18	        throw new Exception("INVALID_REQUEST");
    19	      }
    20	
    21	      LocalDate date = LocalDate.parse(dateStr, DATE_FORMATTER);
    22	      String csv = ReportService.getOccupancyReport(date);
    23	
    24	      ctx.contentType("text/csv; charset=utf-8");
    25	      ctx.result(csv);
    26	    } catch (Exception e) {
    27	      handleException(ctx, e);
    28	    }
    29	  }
    30	
    31	  public static void getRevenue(Context ctx) {
    32	    try {
    33	      String monthStr = ctx.queryParam("month");
    34	      if (monthStr == null) {
    35	        throw new Exception("INVALID_REQUEST");
    36	      }
    37	
    38	      String csv = ReportService.getRevenueReport(monthStr);
    39	
    40	      ctx.contentType("text/csv; charset=utf-8");
    41	      ctx.result(csv);
    42	    } catch (Exception e) {
    43	      handleException(ctx, e);
    44	    }
    45	  }
    46	
    47	  private static void handleException(Context ctx, Exception e) {
    48	    String errorCode = e.getMessage();
    49	    int status = 400;
    50	    String message = "";
    51	
    52	    switch (errorCode) {
    53	      case "INVALID_REQUEST":
    54	        status = 400;
    55	        message = "Requisição inválida";
    56	        break;
    57	      default:
    58	        log.error("Unexpected error", e);
    59	        status = 500;
    60	        message = "Erro interno do servidor";
    61	    }
    62	
    63	    ctx.status(status);
    64	    ctx.json(new java.util.HashMap<>(java.util.Map.of("error", errorCode, "message", message)));
    65	  }
    66	}
