     1	package com.pousadamarealta.api;
     2	
     3	import com.pousadamarealta.domain.RatePlan;
     4	import com.pousadamarealta.domain.Reservation;
     5	import com.pousadamarealta.services.ReservationService;
     6	import io.javalin.http.Context;
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	import java.time.format.DateTimeFormatter;
    10	import java.util.HashMap;
    11	import java.util.Map;
    12	import org.slf4j.Logger;
    13	import org.slf4j.LoggerFactory;
    14	
    15	public class ReservationController {
    16	  private static final Logger log = LoggerFactory.getLogger(ReservationController.class);
    17	  private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    18	
    19	  public static void createReservation(Context ctx) {
    20	    try {
    21	      var body = ctx.bodyAsClass(Map.class);
    22	
    23	      Integer roomNumber = ((Number) body.get("roomNumber")).intValue();
    24	      String guestName = (String) body.get("guestName");
    25	      String guestEmail = (String) body.get("guestEmail");
    26	      String guestCpf = (String) body.get("guestCpf");
    27	      String checkInStr = (String) body.get("checkIn");
    28	      String checkOutStr = (String) body.get("checkOut");
    29	      Integer guests = ((Number) body.get("guests")).intValue();
    30	      String ratePlanStr = (String) body.get("ratePlan");
    31	
    32	      LocalDate checkIn = LocalDate.parse(checkInStr, DATE_FORMATTER);
    33	      LocalDate checkOut = LocalDate.parse(checkOutStr, DATE_FORMATTER);
    34	      RatePlan ratePlan = RatePlan.from(ratePlanStr);
    35	
    36	      Reservation reservation = ReservationService.create(
    37	          roomNumber,
    38	          guestName,
    39	          guestEmail,
    40	          guestCpf,
    41	          checkIn,
    42	          checkOut,
    43	          guests,
    44	          ratePlan);
    45	
    46	      ctx.status(201);
    47	      ctx.json(buildReservationDto(reservation));
    48	    } catch (Exception e) {
    49	      handleException(ctx, e);
    50	    }
    51	  }
    52	
    53	  public static void getReservation(Context ctx) {
    54	    try {
    55	      long id = Long.parseLong(ctx.pathParam("id"));
    56	      var reservation = com.pousadamarealta.infrastructure.ReservationRepository.findById(id)
    57	          .orElseThrow(() -> new Exception("RESERVATION_NOT_FOUND"));
    58	      ctx.json(buildReservationDto(reservation));
    59	    } catch (Exception e) {
    60	      handleException(ctx, e);
    61	    }
    62	  }
    63	
    64	  public static void confirmReservation(Context ctx) {
    65	    try {
    66	      long id = Long.parseLong(ctx.pathParam("id"));
    67	      var body = ctx.bodyAsClass(Map.class);
    68	      BigDecimal amountPaid = BigDecimal.valueOf(((Number) body.get("amountPaid")).doubleValue());
    69	
    70	      Reservation reservation = ReservationService.confirm(id, amountPaid);
    71	      ctx.json(buildReservationDto(reservation));
    72	    } catch (Exception e) {
    73	      handleException(ctx, e);
    74	    }
    75	  }
    76	
    77	  public static void cancelReservation(Context ctx) {
    78	    try {
    79	      long id = Long.parseLong(ctx.pathParam("id"));
    80	      Reservation reservation = ReservationService.cancel(id);
    81	      ctx.json(buildReservationDto(reservation));
    82	    } catch (Exception e) {
    83	      handleException(ctx, e);
    84	    }
    85	  }
    86	
    87	  public static void checkInReservation(Context ctx) {
    88	    try {
    89	      long id = Long.parseLong(ctx.pathParam("id"));
    90	      Reservation reservation = ReservationService.checkIn(id);
    91	      ctx.json(buildReservationDto(reservation));
    92	    } catch (Exception e) {
    93	      handleException(ctx, e);
    94	    }
    95	  }
    96	
    97	  public static void checkOutReservation(Context ctx) {
    98	    try {
    99	      long id = Long.parseLong(ctx.pathParam("id"));
   100	      Reservation reservation = ReservationService.checkOut(id);
   101	      ctx.json(buildDocumentDto(reservation));
   102	    } catch (Exception e) {
   103	      handleException(ctx, e);
   104	    }
   105	  }
   106	
   107	  public static void getDocument(Context ctx) {
   108	    try {
   109	      long id = Long.parseLong(ctx.pathParam("id"));
   110	      var reservation = com.pousadamarealta.infrastructure.ReservationRepository.findById(id)
   111	          .orElseThrow(() -> new Exception("RESERVATION_NOT_FOUND"));
   112	
   113	      if (reservation.status.name().equals("PENDING")) {
   114	        throw new Exception("OPERATION_NOT_ALLOWED");
   115	      }
   116	
   117	      ctx.json(buildDocumentDto(reservation));
   118	    } catch (Exception e) {
   119	      handleException(ctx, e);
   120	    }
   121	  }
   122	
   123	  private static Map<String, Object> buildReservationDto(Reservation res) {
   124	    Map<String, Object> dto = new HashMap<>();
   125	    dto.put("id", res.id);
   126	    dto.put("roomNumber", res.roomNumber);
   127	    dto.put("guestName", res.guestName);
   128	    dto.put("guestEmail", res.guestEmail);
   129	    dto.put("guestCpf", res.guestCpf);
   130	    dto.put("checkIn", res.checkIn.format(DATE_FORMATTER));
   131	    dto.put("checkOut", res.checkOut.format(DATE_FORMATTER));
   132	    dto.put("guests", res.guests);
   133	    dto.put("ratePlan", res.ratePlan.value);
   134	    dto.put("nights", res.nights);
   135	    dto.put("subtotal", res.subtotal);
   136	    dto.put("discount", res.discount);
   137	    dto.put("total", res.total);
   138	    dto.put("status", res.status.value);
   139	    dto.put("amountPaid", res.amountPaid);
   140	    dto.put("refund", res.refund);
   141	    return dto;
   142	  }
   143	
   144	  private static Map<String, Object> buildDocumentDto(Reservation res) throws Exception {
   145	    var room = com.pousadamarealta.infrastructure.RoomRepository.findById(res.roomNumber);
   146	    if (room.isEmpty()) {
   147	      throw new RuntimeException("Room not found");
   148	    }
   149	
   150	    Map<String, Object> dto = new HashMap<>();
   151	    dto.put("title", "Comprovante de reserva");
   152	    dto.put("reservationId", res.id);
   153	    dto.put("guestName", res.guestName);
   154	    dto.put("guestCpf", res.guestCpf);
   155	    dto.put("roomNumber", res.roomNumber);
   156	    dto.put("roomType", room.get().type.value);
   157	    dto.put("checkIn", res.checkIn.format(DateTimeFormatter.ofPattern("dd/MM/yyyy")));
   158	    dto.put("checkOut", res.checkOut.format(DateTimeFormatter.ofPattern("dd/MM/yyyy")));
   159	    dto.put("nights", res.nights);
   160	    dto.put("subtotal", res.subtotal);
   161	    dto.put("discount", res.discount);
   162	    dto.put("total", res.total);
   163	    return dto;
   164	  }
   165	
   166	  private static void handleException(Context ctx, Exception e) {
   167	    String errorCode = e.getMessage();
   168	    int status = 400;
   169	    String message = "";
   170	
   171	    switch (errorCode) {
   172	      case "ROOM_NOT_FOUND":
   173	        status = 404;
   174	        message = "Quarto não encontrado";
   175	        break;
   176	      case "RESERVATION_NOT_FOUND":
   177	        status = 404;
   178	        message = "Reserva não encontrada";
   179	        break;
   180	      case "ROOM_UNAVAILABLE":
   181	        status = 409;
   182	        message = "Quarto indisponível para as datas solicitadas";
   183	        break;
   184	      case "OPERATION_NOT_ALLOWED":
   185	        status = 409;
   186	        message = "Operação não permitida para este estado de reserva";
   187	        break;
   188	      case "CAPACITY_EXCEEDED":
   189	        status = 422;
   190	        message = "Número de hóspedes excede a capacidade do quarto";
   191	        break;
   192	      case "INVALID_REQUEST":
   193	        status = 400;
   194	        message = "Requisição inválida";
   195	        break;
   196	      default:
   197	        log.error("Unexpected error", e);
   198	        status = 500;
   199	        message = "Erro interno do servidor";
   200	    }
   201	
   202	    ctx.status(status);
   203	    Map<String, Object> error = new HashMap<>();
   204	    error.put("error", errorCode);
   205	    error.put("message", message);
   206	    ctx.json(error);
   207	  }
   208	}
