    60	  @Override
    61	  public void onReservationCancelled(ReservationEvent event) throws Exception {
    62	    Reservation current = event.reservation();
    63	    Reservation previous = event.previousReservation();
    64	
    65	    if (previous == null || previous.status.equals(com.pousadamarealta.domain.ReservationStatus.PENDING)) {
    66	      return;
