   107	  private String buildReceipt(Reservation res, com.pousadamarealta.domain.Room room) {
   108	    StringBuilder receipt = new StringBuilder();
   109	    receipt.append("Comprovante de reserva nº ").append(res.id).append("\n");
   110	    receipt.append("Hóspede: ").append(res.guestName).append(" (CPF ")
   111	        .append(formatCpf(res.guestCpf)).append(")\n");
   112	    receipt.append("Quarto: ").append(res.roomNumber).append(" (").append(room.type.value).append(")\n");
   113	
   114	    String nightsLabel = res.nights == 1 ? "1 diária" : res.nights + " diárias";
   115	    receipt.append("Entrada: ").append(res.checkIn.format(DATE_FORMATTER)).append(" | ");
   116	    receipt.append("Saída: ").append(res.checkOut.format(DATE_FORMATTER)).append(" | ");
   117	    receipt.append(nightsLabel).append("\n");
   118	
   119	    receipt.append("Diárias: R$ ").append(formatMoney(res.subtotal)).append("\n");
   120	
   121	    if (res.discount.signum() > 0) {
   122	      receipt.append("Desconto: R$ ").append(formatMoney(res.discount)).append("\n");
   123	    }
   124	
   125	    receipt.append("Total: R$ ").append(formatMoney(res.total));
   126	
   127	    return receipt.toString();
   128	  }
   129	
   130	  private String buildGuestConfirmationEmail(Reservation res, String receipt) {
   131	    return String.format(
   132	        "Olá, %s!%n%n"
   133	            + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:%n%n"
   134	            + "%s%n%n"
   135	            + "A entrada é a partir das 14h, e a saída, até as 12h.%n"
   136	            + "Até breve!",
   137	        res.guestName, receipt);
   138	  }
   139	
   140	  private String formatCpf(String cpf) {
   141	    if (cpf.length() != 11) return cpf;
   142	    return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-"
   143	        + cpf.substring(9);
   144	  }
   145	
   146	  private String formatMoney(java.math.BigDecimal value) {
   147	    return String.format("%.2f", value);
   148	  }
   149	}
