     1	package com.pousadamarealta.services;
     2	
     3	import com.pousadamarealta.domain.Reservation;
     4	import com.pousadamarealta.domain.ReservationStatus;
     5	import com.pousadamarealta.infrastructure.ReservationRepository;
     6	import com.pousadamarealta.infrastructure.RoomRepository;
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	import java.time.YearMonth;
    10	import java.time.format.DateTimeFormatter;
    11	import java.util.List;
    12	
    13	public class ReportService {
    14	  private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    15	
    16	  public static String getOccupancyReport(LocalDate date) throws Exception {
    17	    List<Reservation> reservations = ReservationRepository.findConfirmedOnDate(date);
    18	    var rooms = RoomRepository.findAll();
    19	
    20	    StringBuilder csv = new StringBuilder();
    21	    csv.append("room,type,reservation,check_in,check_out\n");
    22	
    23	    var occupiedRoomNumbers = new java.util.HashSet<Integer>();
    24	    for (var room : rooms) {
    25	      var roomReservation = reservations.stream()
    26	          .filter(r -> r.roomNumber == room.number)
    27	          .findFirst();
    28	
    29	      if (roomReservation.isPresent()) {
    30	        var res = roomReservation.get();
    31	        csv.append(room.number).append(",")
    32	            .append(room.type.value).append(",")
    33	            .append(res.id).append(",")
    34	            .append(res.checkIn.format(DATE_FORMATTER)).append(",")
    35	            .append(res.checkOut.format(DATE_FORMATTER)).append("\n");
    36	        occupiedRoomNumbers.add(room.number);
    37	      }
    38	    }
    39	
    40	    csv.append("total,").append(occupiedRoomNumbers.size()).append("/").append(rooms.size());
    41	
    42	    return csv.toString();
    43	  }
    44	
    45	  public static String getRevenueReport(String monthStr) throws Exception {
    46	    String[] parts = monthStr.split("-");
    47	    if (parts.length != 2) {
    48	      throw new Exception("INVALID_REQUEST");
    49	    }
    50	
    51	    int year = Integer.parseInt(parts[0]);
    52	    int month = Integer.parseInt(parts[1]);
    53	
    54	    List<Reservation> reservations = ReservationRepository.findByMonthStartingInMonth(month, year);
    55	
    56	    StringBuilder csv = new StringBuilder();
    57	    csv.append("reservation,room,check_in,check_out,status,amount\n");
    58	
    59	    BigDecimal total = BigDecimal.ZERO;
    60	    for (var res : reservations) {
    61	      if (res.amountPaid.signum() > 0) {
    62	        BigDecimal amount = res.amountPaid.subtract(res.refund != null ? res.refund : BigDecimal.ZERO);
    63	        csv.append(res.id).append(",")
    64	            .append(res.roomNumber).append(",")
    65	            .append(res.checkIn.format(DATE_FORMATTER)).append(",")
    66	            .append(res.checkOut.format(DATE_FORMATTER)).append(",")
    67	            .append(res.status.value).append(",")
    68	            .append(String.format("%.2f", amount)).append("\n");
    69	        total = total.add(amount);
    70	      }
    71	    }
    72	
    73	    csv.append("total,,,,,").append(String.format("%.2f", total));
    74	
    75	    return csv.toString();
    76	  }
    77	}
