    55	
    56	    StringBuilder csv = new StringBuilder();
    57	    csv.append("reservation,room,check_in,check_out,status,amount\n");
    58	
    59	    BigDecimal total = BigDecimal.ZERO;
    60	    for (var res : reservations) {
