   112	    if (!res.status.equals(ReservationStatus.CONFIRMED)) {
   113	      throw new Exception("OPERATION_NOT_ALLOWED");
   114	    }
   115	
   116	    ReservationRepository.updateStatus(id, ReservationStatus.CHECKED_IN);
   117	    Reservation checkedIn = ReservationRepository.findById(id).orElseThrow();
   118	
   119	    ReservationEventPublisher.publishCheckedIn(new ReservationEvent(ReservationEvent.EventType.CHECKED_IN, checkedIn));
   120	
   121	    return checkedIn;
   122	  }
   123	
   124	  public static Reservation checkOut(long id) throws Exception {
   125	    Reservation res = ReservationRepository.findById(id)
   126	        .orElseThrow(() -> new Exception("RESERVATION_NOT_FOUND"));
   127	
   128	    if (!res.status.equals(ReservationStatus.CHECKED_IN)) {
   129	      throw new Exception("OPERATION_NOT_ALLOWED");
   130	    }
   131	
   132	    ReservationRepository.updateStatus(id, ReservationStatus.CHECKED_OUT);
   133	    Reservation checkedOut = ReservationRepository.findById(id).orElseThrow();
   134	
   135	    ReservationEventPublisher.publishCheckedOut(new ReservationEvent(ReservationEvent.EventType.CHECKED_OUT, checkedOut));
   136	
   137	    return checkedOut;
   138	  }
