     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class PriceCalculator {
     8	  private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.2);
     9	
    10	  public static boolean isHighSeason(LocalDate date) {
    11	    int month = date.getMonthValue();
    12	    int day = date.getDayOfMonth();
    13	
    14	    if (month == 7) return true;
    15	    if (month == 12) return day >= 15;
    16	    if (month == 1 || month == 2) return true;
    17	
    18	    return false;
    19	  }
    20	
    21	  public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
    22	    BigDecimal price = baseRate;
    23	    if (isHighSeason(date)) {
    24	      price = price.multiply(HIGH_SEASON_MULTIPLIER);
    25	    }
    26	    return round(price);
    27	  }
    28	
    29	  public static BigDecimal calculateSubtotal(BigDecimal nightlyPrice, int nights) {
    30	    BigDecimal subtotal = nightlyPrice.multiply(BigDecimal.valueOf(nights));
    31	    return round(subtotal);
    32	  }
    33	
    34	  public static BigDecimal calculateDiscount(BigDecimal subtotal, double discountRate) {
    35	    if (discountRate == 0) {
    36	      return BigDecimal.ZERO;
    37	    }
    38	    BigDecimal discount = subtotal.multiply(BigDecimal.valueOf(discountRate));
    39	    return round(discount);
    40	  }
    41	
    42	  public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    43	    BigDecimal total = subtotal.subtract(discount);
    44	    return round(total);
    45	  }
    46	
    47	  public static BigDecimal round(BigDecimal value) {
    48	    return value.setScale(2, RoundingMode.HALF_EVEN);
    49	  }
    50	}
