 1	package com.pousadamarealta;
 2	
 3	import com.pousadamarealta.infrastructure.PriceCalculator;
 4	import java.math.BigDecimal;
 5	import java.time.LocalDate;
 6	import org.junit.jupiter.api.Test;
 7	
 8	import static org.junit.jupiter.api.Assertions.*;
 9	
10	public class PriceCalculatorTest {
11	  @Test
12	  public void testHighSeasonInJuly() {
13	    assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 7, 10)));
14	  }
15	
16	  @Test
17	  public void testHighSeasonInDecember() {
18	    assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 12, 15)));
19	    assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 12, 14)));
20	  }
21	
22	  @Test
23	  public void testHighSeasonInJanuary() {
24	    assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 1, 15)));
25	  }
26	
27	  @Test
28	  public void testLowSeason() {
29	    assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 5, 15)));
30	  }
31	
32	  @Test
33	  public void testNightlyPriceWithHighSeasonMultiplier() {
34	    BigDecimal baseRate = BigDecimal.valueOf(249.90);
35	    BigDecimal price = PriceCalculator.calculateNightlyPrice(baseRate, LocalDate.of(2027, 7, 10));
36	    assertEquals(new BigDecimal("299.88"), price);
37	  }
38	
39	  @Test
40	  public void testExample() {
41	    BigDecimal baseRate = BigDecimal.valueOf(249.90);
42	    BigDecimal nightlyPrice = PriceCalculator.calculateNightlyPrice(baseRate, LocalDate.of(2027, 7, 10));
43	    assertEquals(new BigDecimal("299.88"), nightlyPrice);
44	
45	    BigDecimal subtotal = nightlyPrice.multiply(BigDecimal.valueOf(2));
46	    subtotal = PriceCalculator.round(subtotal);
47	    assertEquals(new BigDecimal("599.76"), subtotal);
48	  }
49	}

